-- Five original supports for grade-eight writing, term one; historical OCR titles remain unchanged.
WITH qa(n,skill,passage,prompt,correct,w1,w2,w3,practice) AS (VALUES (15,'وصف المكان: إثراء','دخل الطلاب قاعة معرض للكتاب؛ لاحظوا الأرفف المنظمة والممرات الواسعة ورائحة الورق. ميزت المعلمة بين وصف داخل المكان وبين وصف واجهته الخارجية، ثم ربطت الوصف بحركة الشخصيات.','ما تفصيل وصف القاعة من الداخل؟','الأرفف المنظمة والممرات','حالة الطقس خارج المدينة','اسم طريق بعيد','لون حذاء البطل','أكتب وصفًا لمكان مغلق بثلاثة تفاصيل حسية، ثم أدخل شخصية تتحرك فيه.'),
(16,'وصف المكان: تعرّف','وقفت سارة في ساحة المدرسة فرأت الأشجار والمقاعد تحت الشمس، ثم دخلت المكتبة ولاحظت هدوءها ورفوفها. قسمت وصفها إلى مكان مفتوح ومكان مغلق ولم تخلط خصائص أحدهما بالآخر.','أي مكان في المثال مفتوح؟','ساحة المدرسة','غرفة المكتبة','القاعة الداخلية','المختبر','صف ساحة مفتوحة وغرفة مغلقة، وقارن بين الضوء والصوت فيهما.'),
(17,'وصف المكان: إنتاج','بدأ أحمد قصة في حديقة مليئة بالأشجار؛ ثم انتقل إلى غرفة صغيرة عندما هطل المطر. لاحظ اختلاف الضوء والصوت بين المكانين؛ فجعل الوصف يمهد لتغير حركة الشخصيات.','كيف يفيد وصف المكانين؟','يوضح انتقال الحدث بين مشهدين','يُلغي زمن القصة','يجعل المكانين متطابقين','يمنع ظهور الشخصيات','اكتب قصة قصيرة تنتقل من مكان مفتوح إلى مغلق، مع وصف حسّي لكل منهما.'),
(18,'تلخيص القصة: الأحداث','فقدت عائشة دفترها في المدرسة، فبحثت في الصف ثم سألت أمينة المكتبة. وجدت الأمينة الدفتر على رف وأعادته إليها. لخصت هدى القصة بذكر المشكلة والبحث والحل دون وصف لون الدفتر.','ما الحدث الأساسي للملخص؟','ضياع الدفتر والعثور عليه','لون الغلاف','عدد نوافذ الفصل','وقت الاستراحة','لخّص قصة الدفتر في جملتين مع الحفاظ على السبب والحدث والحل.'),
(19,'تلخيص القصة: الاختصار','زرع الطلاب شتلة في فناء المدرسة وتابعوا سقيها حتى نمت. وصف النص الأصص والأدوات وألوانها؛ أبقى حمد في ملخصه الفعل الرئيس والعناية والنتيجة، واستبعد أوصافًا لا تغيّر الفكرة.','ما التفصيل الذي يمكن الاستغناء عنه؟','لون الأصص','زراعة الشتلة','السقي المستمر','نمو النبات','اكتب ملخصًا من ثلاث جمل عن زرع الشتلة، ثم احذف وصفين لا يخدمان فكرته.'))
UPDATE public.lessons l SET content='ضاديوم — تمرين كتابة أصلي للصف الثامن الفصل الأول؛ العنوان المستورد يحتاج مراجعة ولا يمثل نص الكتاب الرسمي.'||E'\n\n'||
'المهارة: '||qa.skill||E'\n\n'||'المثال الداعم: '||qa.passage||E'\n\n'||'أفهم وأحلل: '||qa.prompt||E'\n\n'||'أطبق: '||qa.practice||E'\n\n'||
'أهداف قابلة للقياس: أن يحدد الطالب الدليل في المثال، ويفرق بين الوصف والحدث أو بين التفصيل والفكرة، ثم يكتب فقرة مستقلة.'||E'\n\n'||
'دعم التعلم: يقدم المعلم كلمات مفتاحية وأمثلة قصيرة للمبتدئ، ويطلب من المتوسط إعادة الصياغة، ويكلف المتقدم بتحرير النص وتفسير تعديلاته.'||E'\n\n'||
'تحقق الجودة: يراجع المعلم الصياغة والترابط وعلامات الترقيم. إنجاز مهمة إلكترونية لا يساوي تصحيح الكتابة آليًا.'||E'\n\n'||
'الوصف القديم المحفوظ: '||l.content,updated_at=now()
FROM qa JOIN public.units u ON u.title='التعبير والكتابة' AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.unit_id=u.id AND l.sort_order=qa.n AND l.status='published'
AND l.content LIKE 'يتناول هذا الدرس موضوع%' AND length(l.content)<350;
WITH qa(n,skill,passage,prompt,correct,w1,w2,w3,practice) AS (VALUES (15,'وصف المكان: إثراء','دخل الطلاب قاعة معرض للكتاب؛ لاحظوا الأرفف المنظمة والممرات الواسعة ورائحة الورق. ميزت المعلمة بين وصف داخل المكان وبين وصف واجهته الخارجية، ثم ربطت الوصف بحركة الشخصيات.','ما تفصيل وصف القاعة من الداخل؟','الأرفف المنظمة والممرات','حالة الطقس خارج المدينة','اسم طريق بعيد','لون حذاء البطل','أكتب وصفًا لمكان مغلق بثلاثة تفاصيل حسية، ثم أدخل شخصية تتحرك فيه.'),
(16,'وصف المكان: تعرّف','وقفت سارة في ساحة المدرسة فرأت الأشجار والمقاعد تحت الشمس، ثم دخلت المكتبة ولاحظت هدوءها ورفوفها. قسمت وصفها إلى مكان مفتوح ومكان مغلق ولم تخلط خصائص أحدهما بالآخر.','أي مكان في المثال مفتوح؟','ساحة المدرسة','غرفة المكتبة','القاعة الداخلية','المختبر','صف ساحة مفتوحة وغرفة مغلقة، وقارن بين الضوء والصوت فيهما.'),
(17,'وصف المكان: إنتاج','بدأ أحمد قصة في حديقة مليئة بالأشجار؛ ثم انتقل إلى غرفة صغيرة عندما هطل المطر. لاحظ اختلاف الضوء والصوت بين المكانين؛ فجعل الوصف يمهد لتغير حركة الشخصيات.','كيف يفيد وصف المكانين؟','يوضح انتقال الحدث بين مشهدين','يُلغي زمن القصة','يجعل المكانين متطابقين','يمنع ظهور الشخصيات','اكتب قصة قصيرة تنتقل من مكان مفتوح إلى مغلق، مع وصف حسّي لكل منهما.'),
(18,'تلخيص القصة: الأحداث','فقدت عائشة دفترها في المدرسة، فبحثت في الصف ثم سألت أمينة المكتبة. وجدت الأمينة الدفتر على رف وأعادته إليها. لخصت هدى القصة بذكر المشكلة والبحث والحل دون وصف لون الدفتر.','ما الحدث الأساسي للملخص؟','ضياع الدفتر والعثور عليه','لون الغلاف','عدد نوافذ الفصل','وقت الاستراحة','لخّص قصة الدفتر في جملتين مع الحفاظ على السبب والحدث والحل.'),
(19,'تلخيص القصة: الاختصار','زرع الطلاب شتلة في فناء المدرسة وتابعوا سقيها حتى نمت. وصف النص الأصص والأدوات وألوانها؛ أبقى حمد في ملخصه الفعل الرئيس والعناية والنتيجة، واستبعد أوصافًا لا تغيّر الفكرة.','ما التفصيل الذي يمكن الاستغناء عنه؟','لون الأصص','زراعة الشتلة','السقي المستمر','نمو النبات','اكتب ملخصًا من ثلاث جمل عن زرع الشتلة، ثم احذف وصفين لا يخدمان فكرته.')), s AS (
SELECT l.id,qa.* FROM qa JOIN public.lessons l ON l.sort_order=qa.n AND l.status='published'
JOIN public.units u ON u.id=l.unit_id AND u.title='التعبير والكتابة' AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.content LIKE 'ضاديوم — تمرين كتابة أصلي%' OR (l.content LIKE 'يتناول هذا الدرس موضوع%' AND length(l.content)<350))
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'سؤال فهم أصلي','multiple_choice','assessment',s.prompt,jsonb_build_object('origin','DADYOOM_BH_G8_T1_WRITING_PLACE_SUMMARY_5_20261008','ocrReview','pending','notOfficialBook',true,'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),jsonb_build_object('correct',s.correct),1,5,true,true FROM s
WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T1_WRITING_PLACE_SUMMARY_5_20261008' AND a.activity_type='multiple_choice');
